/**
 * git-merge-generated-hand-text-s474.test.js — the merge driver must never lose HAND-WRITTEN text.
 *
 * Two MED findings from the S474 backfill review (#1695 section; repros d1695/c4c, c5, c5b, c7):
 *   F1 — one side deletes an `@generated` END marker and both sides edit the hand text after it. The
 *        driver filled generated bodies into the CONFLICTED hand-text merge, so ours' unmatched START
 *        paired with theirs' END across the conflict: `<<<<<<<`, ours' edit and `=======` were
 *        replaced as a "generated body", leaving a lone `>>>>>>> theirs` (rc 1, ours' edit gone).
 *   F2 — one side gains a `<!-- @generated by` line in its first 10 lines. The driver took THAT side's
 *        whole file with rc 0, dropping the other side's hand edits — a gap flipped open → resolved
 *        included, which the gap-id count self-check never sees.
 * Fixed: both fall back to the fail block + git's plain 3-way of the original inputs (exit 1), and a
 * hand-text survival self-check backs the gap-id check.
 *
 * Every positive is checked against the base driver: each test here fails on the pre-fix driver.
 * Conflict markers are built with `"<".repeat(7)` — a literal marker at line start in a tracked file
 * trips scripts/conflict-marker-gate.ts.
 */

import { describe, test, expect } from "bun:test";
import { mkdtempSync, mkdirSync, copyFileSync, readFileSync, writeFileSync, rmSync } from "node:fs";
import { join, dirname } from "node:path";
import { tmpdir } from "node:os";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import * as M from "../../../scripts/git-merge-generated.ts";

const REPO = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
const OPEN = "<".repeat(7);
const SEP = "=".repeat(7);
const CLOSE = ">".repeat(7);
const PATH = "docs/known-gaps.md";
const markerLines = (t) => t.split("\n").filter((l) => /^(<{7}|={7}|>{7})( |\r?$)/.test(l));
const count = (t, prefix) => markerLines(t).filter((l) => l.startsWith(prefix)).length;

// ── the repro inputs, verbatim from ~/.cache/scrml/review/s474-backfill/d1695 ──
const C4C = {
  o: "# Gaps\n\nintro line\n\n<!-- @generated:foo START -->\nfoo 1\n<!-- @generated:foo END -->\nhand A\n\n## end\n",
  a: "# Gaps\n\nintro line\n\n<!-- @generated:foo START -->\nfoo 1\nhand A OURS-EDIT\n\n## end\n",
  b: "# Gaps\n\nintro line\n\n<!-- @generated:foo START -->\nfoo 1\n<!-- @generated:foo END -->\nhand A theirs\n\n## end\n",
};
const C5 = {
  o: "# Facts\n\nhand one\nhand two\n\n## end\n",
  a: "# Facts\n<!-- @generated by nobody: note -->\nhand one\nhand two\n\n## end\n",
  b: "# Facts\n\nhand one THEIRS\nhand two\n\n## end\n",
};
const C5B = {
  o: "# Facts\n\nhand one\nhand two\n\n## end\n",
  a: "# Facts\n\nhand one OURS\nhand two\n\n## end\n",
  b: "# Facts\n<!-- @generated by x -->\nhand one\nhand two\n\n## end\n",
};
const C7 = {
  o: "# Gaps\n\n### g-a\n<!-- @gap id=g-a sev=LOW status=open -->\n",
  a: "# Gaps\n<!-- @generated by note -->\n### g-a\n<!-- @gap id=g-a sev=LOW status=open -->\n",
  b: "# Gaps\n\n### g-a\n<!-- @gap id=g-a sev=LOW status=resolved -->\n",
};

/** Run the REAL wrapper the way git does (`sh scripts/git-merge-generated.sh %O %A %B %P %L %S %X %Y`). */
function viaWrapper({ o, a, b }) {
  const dir = mkdtempSync(join(process.env.TMPDIR || tmpdir(), "scrml-mgd-s474-"));
  try {
    // The wrapper runs `bun scripts/git-merge-generated.ts` from its cwd (git runs it from the top of
    // ours' tree), so give it a scripts/ dir. The temp dir is not a repo: no pending record is written.
    mkdirSync(join(dir, "scripts"));
    for (const f of ["git-merge-generated.ts", "git-merge-generated.sh", "state.ts"]) copyFileSync(join(REPO, "scripts", f), join(dir, "scripts", f));
    const po = join(dir, "o"), pa = join(dir, "A"), pb = join(dir, "b");
    writeFileSync(po, o); writeFileSync(pa, a); writeFileSync(pb, b);
    // strip GIT_* (the pre-commit hook exports GIT_INDEX_FILE / GIT_DIR)
    const env = Object.fromEntries(Object.entries(process.env).filter(([k]) => !k.startsWith("GIT_")));
    const r = spawnSync("sh", ["scripts/git-merge-generated.sh", po, pa, pb, PATH, "7", "base", "ours", "theirs"], {
      cwd: dir, encoding: "utf8", env: { ...env, GIT_CEILING_DIRECTORIES: dirname(dir) },
    });
    return { rc: r.status, text: readFileSync(pa, "utf8"), stderr: r.stderr };
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

describe("F1 — a deleted END marker never swallows a side of a hand-text conflict", () => {
  test("BITE: plain git merge-file keeps both sides (the oracle)", () => {
    const plain = M.gitMergeFile(C4C.o, C4C.a, C4C.b, 7, { ours: "ours", base: "base", theirs: "theirs" });
    expect(plain.conflicts).toBeGreaterThan(0);
    expect(plain.text).toContain("hand A OURS-EDIT");
    expect(plain.text).toContain("hand A theirs");
  });

  test("the driver keeps ours' AND theirs' edit, with balanced markers, and refuses (fallback)", () => {
    const r = M.mergeGenerated(C4C.o, C4C.a, C4C.b, PATH);
    expect(r.text).toContain("hand A OURS-EDIT"); // pre-fix: gone
    expect(r.text).toContain("hand A theirs");
    expect(r.conflicts).toBeGreaterThan(0);
    expect(r.fallback).toBeTruthy();
    expect(count(r.text, OPEN)).toBe(count(r.text, CLOSE)); // pre-fix: 0 opens, 1 close
    expect(count(r.text, OPEN)).toBeGreaterThanOrEqual(2); // fail block + the real conflict
    expect(count(r.text, SEP)).toBe(count(r.text, OPEN));
  });

  test("end to end through the .sh wrapper: rc 1, both edits on the page, balanced markers", () => {
    const w = viaWrapper(C4C);
    expect(w.rc).toBe(1);
    expect(w.text).toContain("hand A OURS-EDIT");
    expect(w.text).toContain("hand A theirs");
    expect(count(w.text, OPEN)).toBe(count(w.text, CLOSE));
    expect(w.text).toContain("scrml-generated-merge:");
  }, 30_000);
});

describe("F2 — a one-sided `@generated by` header never takes that side whole", () => {
  for (const [name, c, kept] of [
    ["c5 (ours gains the header, theirs edits hand text)", C5, "hand one THEIRS"],
    ["c5b (theirs gains the header, ours edits hand text)", C5B, "hand one OURS"],
    ["c7 (ours gains the header, theirs resolves a gap)", C7, "status=resolved"],
  ]) {
    test(`BITE ${name}: the other side's edit survives and the merge stops`, () => {
      const r = M.mergeGenerated(c.o, c.a, c.b, PATH);
      expect(r.text).toContain(kept); // pre-fix: dropped, rc 0
      expect(r.fallback).toBeTruthy();
      expect(r.conflicts).toBeGreaterThan(0);
      expect(r.text).toContain(OPEN);
    });
  }

  test("end to end through the .sh wrapper (c7): rc 1, the resolution is not lost", () => {
    const w = viaWrapper(C7);
    expect(w.rc).toBe(1); // pre-fix: 0
    expect(w.text).toContain("status=resolved");
    expect(w.text).toContain("<!-- @generated by note -->"); // ours' header is not lost either
  }, 30_000);

  test("a file wholly generated on EVERY side is still taken whole (no markers from the text merge)", () => {
    const g = (n) => `# Bootstrap conformance — generated\n\n<!-- @generated by \`bun scripts/bootstrap-conformance.ts --write\`. -->\n\n| PASS | ${n} |\n`;
    const r = M.mergeGenerated(g(1), g(1), g(3), "docs/bootstrap-conformance.md");
    expect(r.fallback).toBeNull();
    expect(r.conflicts).toBe(0);
    expect(r.text).toBe(g(3));
    // add/add (empty base) of two wholly-generated sides is a whole-file merge too
    expect(M.mergeGenerated("", g(2), g(3), "docs/bootstrap-conformance.md").fallback).toBeNull();
  });
});

describe("hand-text survival self-check", () => {
  test("BITE: it names the hand edit the pre-fix driver dropped (c4c output, c7 output)", () => {
    // the exact pre-fix driver outputs, from the review
    const c4cBad = "# Gaps\n\nintro line\n\n<!-- @generated:foo START -->\nfoo 1\n<!-- @generated:foo END -->\nhand A theirs\n" + CLOSE + " theirs\n\n## end\n";
    expect(M.handTextSelfCheck(C4C.o, C4C.a, C4C.b, c4cBad, PATH)).toContain("hand A OURS-EDIT");
    expect(M.handTextSelfCheck(C7.o, C7.a, C7.b, C7.a, PATH)).toEqual(["<!-- @gap id=g-a sev=LOW status=resolved -->"]);
    // the gap-id check alone passes that c7 result — the hole this closes
    expect(M.gapIdSelfCheck(C7.o, C7.a, C7.b, C7.a)).toEqual({ dropped: [], duplicated: [], ambiguous: [] });
  });

  test("no false failure: an IDENTICAL edit on both sides kept once, a one-sided deletion, edits inside markers", () => {
    const o = "a\nb\nc\n", same = "a\nB!\nc\n";
    expect(M.handTextSelfCheck(o, same, same, same, PATH)).toEqual([]);
    expect(M.handTextSelfCheck(o, "a\nc\n", o, "a\nc\n", PATH)).toEqual([]);
    const conflicted = `a\n${OPEN} ours\nB1\n${SEP}\nB2\n${CLOSE} theirs\nc\n`;
    expect(M.handTextSelfCheck(o, "a\nB1\nc\n", "a\nB2\nc\n", conflicted, PATH)).toEqual([]);
    // generated bodies are not hand text: a changed body line need not survive
    const gen = (x) => `h\n<!-- @generated:foo START -->\n${x}\n<!-- @generated:foo END -->\n`;
    expect(M.handTextSelfCheck(gen("1"), gen("2"), gen("1"), gen("3"), PATH)).toEqual([]);
  });

  test("a clean driver merge passes it (both sides' hand edits present)", () => {
    const o = "# G\n\nx\n\ny\n\nz\n", a = "# G\n\nx OURS\n\ny\n\nz\n", b = "# G\n\nx\n\ny\n\nz THEIRS\n";
    const r = M.mergeGenerated(o, a, b, PATH);
    expect(r.conflicts).toBe(0);
    expect(r.fallback).toBeNull();
    expect(r.lostHandLines).toEqual([]);
  });
});

describe("LOW — the wrapper's fail-closed banner no longer points at `state.ts --write`", () => {
  test("the banner advises merging main and leaving docs/generated/ to the bot", () => {
    const sh = readFileSync(join(REPO, "scripts/git-merge-generated.sh"), "utf8");
    const printfs = sh.split("\n").filter((l) => l.trimStart().startsWith("printf"));
    expect(printfs.join("\n")).not.toContain("state.ts --write"); // pre-fix: the closing banner line said it
    expect(printfs.join("\n")).toContain("docs/generated/");
  });
});

// ── S474 #1726 review round 1 ────────────────────────────────────────────────────────────────────

describe("N1 — the hand-text check counts base copies (duplicated and moved lines)", () => {
  const F = "`".repeat(3);
  test("BITE: a changed line that already occurs elsewhere in base, then lost, is named", () => {
    const o = "x\nFixed.\nold wording\n", a = "x\nFixed.\nFixed.\n", b = o;
    // the result kept base's one `Fixed.` but lost ours' rewrite of `old wording` into a second one
    expect(M.handTextSelfCheck(o, a, b, o, PATH)).toEqual(["Fixed."]);
  });

  test("BITE: a line MOVED between sections, then lost, is named", () => {
    const o = "## S1\nentry E\n## S2\n", a = "## S1\n## S2\nentry E\n";
    expect(M.handTextSelfCheck(o, a, o, "## S1\n## S2\n", PATH)).toEqual(["entry E"]);
  });

  test("BITE: a lost CODE-FENCE line (a line base already holds many copies of) is named", () => {
    const o = `t\n${F}\none\n${F}\n\nu\n${F}\ntwo\n${F}\n`;
    const a = o + `\n${F}\nthree\n${F}\n`;
    const lostOne = a.slice(0, a.length - (F.length + 1)); // ours' closing fence gone: text below flips to fenced
    expect(lostOne.endsWith("three\n")).toBe(true);
    expect(M.handTextSelfCheck(o, a, o, lostOne, PATH)).toEqual([F]);
  });

  test("no false failure: one side deletes a copy while the other adds one; both delete the same line", () => {
    const o = "a\n---\nb\n---\nc\n";
    const a = "a\nb\n---\nc\n";             // deletes a copy
    const b = "a\n---\nb\n---\nc\n---\n";   // adds a copy
    expect(M.handTextSelfCheck(o, a, b, "a\nb\n---\nc\n---\n", PATH)).toEqual([]);
    expect(M.handTextSelfCheck(o, "a\nb\nc\n", "a\nb\nc\n", "a\nb\nc\n", PATH)).toEqual([]);
  });

  test("REAL ledger: a move, a duplicated-line insert and a deleted fence pair merge clean with NO false loss — and the move dropped is caught", () => {
    const base = readFileSync(join(REPO, "docs/known-gaps.md"), "utf8").replace(/\r\n/g, "\n");
    const L = base.split("\n");
    const heads = L.map((l, i) => (l.startsWith("### ") ? i : -1)).filter((i) => i >= 0);
    expect(heads.length).toBeGreaterThan(100);
    // theirs: delete the first fence pair in the file (the fence's content stays)
    const fo = L.findIndex((l, i) => i > 0 && /^`{3}\S/.test(l));
    const fc = L.findIndex((l, i) => i > fo && l === F);
    expect(fo).toBeGreaterThan(0);
    expect(fc).toBeLessThan(L.length / 5);
    const theirs = L.filter((_, i) => i !== fo && i !== fc).join("\n");
    // ours: move one entry from the last fifth to before an entry in the middle, and insert a `---`
    // (a line base holds many copies of) near the 3/5 mark
    const hFrom = heads.find((i) => i > (L.length * 4) / 5);
    const hNext = heads.find((i) => i > hFrom);
    const hTo = heads.find((i) => i > L.length / 2);
    const hDash = heads.find((i) => i > (L.length * 3) / 5);
    const moved = L.slice(hFrom, hNext);
    const ours = [];
    for (let i = 0; i < L.length; i++) {
      if (i >= hFrom && i < hNext) continue;
      if (i === hTo) ours.push(...moved);
      if (i === hDash) ours.push("---", "");
      ours.push(L[i]);
    }
    const a = ours.join("\n");
    const r = M.mergeGenerated(base, a, theirs, PATH);
    expect(r.fallback).toBeNull();
    expect(r.conflicts).toBe(0);
    expect(r.lostHandLines).toEqual([]);
    expect(r.text).toContain(moved.join("\n"));
    const fences = (t) => t.split("\n").filter((l) => /^`{3}/.test(l)).length;
    expect(fences(r.text)).toBe(fences(base) - 2);
    // …and the same result with the moved entry dropped is caught (the pre-N1 formula passed it)
    const dropped = r.text.replace(moved.join("\n") + "\n", "");
    expect(dropped).not.toBe(r.text);
    expect(M.handTextSelfCheck(base, a, theirs, dropped, PATH)).toContain(moved[0]);
  }, 30_000);
});

describe("N2 — a failed hand-text self-check is exit 1 with a fail block (driver wiring)", () => {
  test("runDriver: a merge result with lost hand lines → rc 1, fail block over git's plain 3-way", () => {
    const dir = mkdtempSync(join(process.env.TMPDIR || tmpdir(), "scrml-mgd-n2-"));
    try {
      const o = "a\nb\nc\n", a = "a\nb OURS\nc\n", b = "a\nb\nc THEIRS\n";
      const po = join(dir, "o"), pa = join(dir, "A"), pb = join(dir, "b");
      writeFileSync(po, o); writeFileSync(pa, a); writeFileSync(pb, b);
      // a merge that "forgot" ours' edit and says so through lostHandLines
      const fake = () => ({
        text: "a\nb\nc THEIRS\n", conflicts: 0, pending: false, regenerated: [], provisional: [], unioned: 0,
        needsRegen: [], selfCheck: { dropped: [], duplicated: [], ambiguous: [] }, lostHandLines: ["b OURS"], fallback: null,
      });
      const rc = M.runDriver([po, pa, pb, PATH, "7", "base", "ours", "theirs"], fake);
      expect(rc).toBe(1);
      const out = readFileSync(pa, "utf8");
      expect(markerLines(out).slice(0, 3).map((l) => l.slice(0, 7))).toEqual([OPEN, SEP, CLOSE]);
      expect(out).toContain("HAND-TEXT SELF-CHECK FAILED");
      expect(out).toContain("b OURS"); // git's plain 3-way follows: both edits on the page
      expect(out).toContain("c THEIRS");
      expect(readFileSync(pa + ".scrml-done", "utf8")).toBe("1");
      // control: the same fake with nothing lost is a clean rc 0
      writeFileSync(pa, a);
      expect(M.runDriver([po, pa, pb, PATH, "7", "base", "ours", "theirs"], () => ({ ...fake(), lostHandLines: [] }))).toBe(0);
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
});

describe("N3 — the whole-file rule needs the BASE wholly generated too", () => {
  test("base hand text, both sides wholly generated → fallback, never a whole-file pick", () => {
    const g = (n) => `# T\n<!-- @generated by \`bun scripts/x.ts --write\`. -->\n\n| PASS | ${n} |\n`;
    const o = "# T\n\nhand-written line\n";
    for (const [a, b] of [[g(1), g(2)], [g(1), g(1)]]) {
      const r = M.mergeGenerated(o, a, b, "docs/bootstrap-conformance.md");
      expect(r.fallback).toBeTruthy();
      expect(r.conflicts).toBeGreaterThan(0);
      expect(r.text).toContain(OPEN);
    }
  });
});

describe("N6 — the banner's --regen hint names every PRODUCERS file", () => {
  test("FACTS.md, SPEC-INDEX.md and bootstrap-conformance.md", () => {
    const banner = readFileSync(join(REPO, "scripts/git-merge-generated.sh"), "utf8").split("\n").filter((l) => l.trimStart().startsWith("printf")).join("\n");
    for (const p of M.PRODUCERS) expect(banner).toContain(p.path.split("/").pop());
  });
});
